INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000263',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss sustainable economy at B2","Use Nachhaltige Wirtschaft vocabulary","Talk about green economy and SDGs"],"explanation":{"intro":"Sustainable economy vocabulary covers green economics, sustainability principles, and German Energiewende at B2.","culturalNote":"Nachhaltige Wirtschaft: Drei Säulen der Nachhaltigkeit (three pillars of sustainability — economic, social, ecological — triple bottom line). Germany: Nachhaltigkeitsstrategie (national sustainability strategy), SDGs (UN Ziele für nachhaltige Entwicklung — SDGs). German strengths: Umwelttechnik (environmental technology — Cleantech), Solar, Wind. Challenges: Kohleausstieg (coal exit — 2038 originally, now earlier), Strukturwandel (structural change — affected regions: Lausitz, Ruhrgebiet). Key concept: Entkopplung (decoupling — economic growth without proportional resource consumption)."},"examples":[{"german":"Eine nachhaltige Wirtschaft strebt nach Entkopplung von wirtschaftlichem Wachstum und Ressourcenverbrauch — eine Transformation, die sowohl technologische Innovation als auch veränderte Konsummuster voraussetzt.","english":"A sustainable economy strives for decoupling of economic growth and resource consumption — a transformation that presupposes both technological innovation and changed consumption patterns."},{"german":"Die deutschen Nachhaltigkeitsziele stehen in einem komplexen Spannungsverhältnis zwischen wirtschaftlicher Wettbewerbsfähigkeit, sozialer Gerechtigkeit und ökologischer Tragfähigkeit.","english":"German sustainability goals are in a complex tension between economic competitiveness, social justice, and ecological sustainability."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss sustainable economy, decoupling, and Germany''s sustainability challenges at B2."}}',
'{"items":[{"word":"anstreben","translation":"to strive for","pronunciation":"AN-shtreh-ben","example":"Entkopplung anstreben."},{"word":"die Entkopplung","translation":"decoupling","pronunciation":"dee ent-KOP-loong","example":"Entkopplung von Wachstum und Ressourcen."},{"word":"voraussetzen","translation":"to presuppose/require","pronunciation":"for-OWS-set-sen","example":"Innovation voraussetzen."},{"word":"die Tragfähigkeit","translation":"sustainability/carrying capacity","pronunciation":"dee TRAHK-fä-ikh-kyt","example":"Ökologische Tragfähigkeit."},{"word":"das Spannungsverhältnis","translation":"tension (relationship)","pronunciation":"dahs SHPAN-oonks-fer-häl-nis","example":"Im Spannungsverhältnis stehen."},{"word":"das Konsummuster","translation":"consumption pattern","pronunciation":"dahs kon-ZOOM-mus-ter","example":"Veränderte Konsummuster."}]}',
'{"title":"Sowohl X als auch Y voraussetzen — to presuppose/require both X and Y","pattern":"etwas setzt sowohl X als auch Y voraus = something presupposes/requires both X and Y (sowohl...als auch = both...and — symmetric, emphasises both elements are equally needed)","explanation":"Voraussetzen + sowohl...als auch = to require/presuppose both X and Y. Separable verb: setzt...voraus. Presupposes (has as a precondition) — stronger than brauchen (to need — practical). Das setzt sowohl Innovation als auch veränderte Konsummuster voraus = This requires both innovation and changed consumption patterns. Sowohl...als auch = both...and (coordinating conjunction — emphasises both elements equally). Compare: nicht nur...sondern auch (not only...but also — additive surprise), entweder...oder (either...or — exclusive), weder...noch (neither...nor — both excluded).","examples":[{"sentence":"Eine gelingende Integration setzt sowohl sprachliche als auch gesellschaftliche Unterstützung voraus.","translation":"Successful integration presupposes both linguistic and societal support."},{"sentence":"Dieses Modell setzt sowohl Vertrauen als auch Transparenz voraus.","translation":"This model presupposes both trust and transparency."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Entkopplung'' means?","options":["decoupling","separation","unbundling","disconnection"],"correctAnswer":"decoupling"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A sustainable economy strives for decoupling of economic growth and resource consumption — a transformation that presupposes both technological innovation and changed consumption patterns.","options":["Eine nachhaltige Wirtschaft strebt nach Entkopplung von wirtschaftlichem Wachstum und Ressourcenverbrauch — eine Transformation, die sowohl technologische Innovation als auch veränderte Konsummuster voraussetzt.","Nachhaltige Wirtschaft bedeutet, Wachstum und Ressourcenverbrauch zu trennen.","Deutschland versucht, Wirtschaftswachstum von ökologischen Auswirkungen zu entkoppeln.","Grünes Wachstum erfordert technologische und gesellschaftliche Veränderungen."],"correctAnswer":"Eine nachhaltige Wirtschaft strebt nach Entkopplung von wirtschaftlichem Wachstum und Ressourcenverbrauch — eine Transformation, die sowohl technologische Innovation als auch veränderte Konsummuster voraussetzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Eine gelingende Integration setzt sowohl sprachliche als auch gesellschaftliche Unterstützung ___.","options":["voraus","vorher","vorwärts","voran"],"correctAnswer":"voraus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This model presupposes both trust and transparency","wordBankItems":["Dieses","Modell","setzt","sowohl","Vertrauen","als","auch","Transparenz","voraus","."],"correctAnswer":"Dieses Modell setzt sowohl Vertrauen als auch Transparenz voraus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Tragfähigkeit'' means?","options":["sustainability/carrying capacity","feasibility","durability","stability"],"correctAnswer":"sustainability/carrying capacity"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000264',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss circular economy at B2","Use Kreislaufwirtschaft vocabulary","Talk about waste reduction and resource loops"],"explanation":{"intro":"Circular economy vocabulary covers waste elimination, resource cycling, and industrial ecology at B2.","culturalNote":"Kreislaufwirtschaft: linear economy (take-make-waste) vs. circular economy (keep materials in use). Key principles: cradle-to-cradle (C2C), Reparaturkultur (repair culture). Germany: Kreislaufwirtschaftsgesetz (Circular Economy Act — 2012), Wertstoffgesetz, Pfandsystem (deposit system — bottles), Getrenntsammlung (separate collection — organic, paper, packaging, residual). Germany leads in recycling rates but debate continues over quality vs. quantity. EU Circular Economy Action Plan. Reuse: Reparieren (repair), Wiederverwenden (reuse), Wiederverwerten (recycle) — hierarchy."},"examples":[{"german":"Das Kreislaufwirtschaftsprinzip stellt das lineare Wirtschaftsmodell grundlegend in Frage, indem es Materialien möglichst lange im Wirtschaftskreislauf hält und Abfall als Ressource begreift.","english":"The circular economy principle fundamentally calls into question the linear economic model, by keeping materials in the economic cycle for as long as possible and conceiving of waste as a resource."},{"german":"Während ein hohes Recyclingvolumen auf effiziente Sammelsysteme hindeutet, ist die eigentliche ökologische Wirkung erst bei hochwertigem Recycling gegeben, das den Materialwert erhält statt ihn zu mindern.","english":"While a high recycling volume indicates efficient collection systems, the actual ecological effect only exists with high-quality recycling that preserves material value rather than diminishing it."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the circular economy, Germany''s recycling system, and waste as resource at B2."}}',
'{"items":[{"word":"grundlegend in Frage stellen","translation":"to fundamentally call into question","pronunciation":"GROONT-lay-gend in FRAH-geh shtel-en","example":"Grundlegend in Frage stellen."},{"word":"begreifen als","translation":"to conceive of as","pronunciation":"beh-GRY-fen als","example":"Abfall als Ressource begreifen."},{"word":"hindeuten auf","translation":"to indicate/point to","pronunciation":"HIN-doy-ten owf","example":"Auf Effizienz hindeuten."},{"word":"hochwertig","translation":"high-quality","pronunciation":"HOHKH-ver-tikh","example":"Hochwertiges Recycling."},{"word":"mindern","translation":"to diminish/reduce","pronunciation":"MIN-dern","example":"Den Wert mindern."},{"word":"erhalten","translation":"to preserve","pronunciation":"er-HAHL-ten","example":"Materialwert erhalten."}]}',
'{"title":"Etwas als X begreifen — to conceive of something as X (reconceptualisation)","pattern":"etwas als X begreifen = to conceive of / understand something as X (begreifen = to comprehend/grasp — as X marks a conceptual reframing)","explanation":"Begreifen als = to conceive of as, to understand as (implies a reconceptualisation — formerly understood as A, now understood as X). Abfall als Ressource begreifen = to conceive of waste as a resource. The als X clause marks the new conceptual category. This is more than just nennen (to call) or betrachten als (to regard as) — begreifen implies a deep rethinking. Compare: betrachten als (to regard as — more neutral evaluation), bezeichnen als (to refer to as — labelling), verstehen als (to understand as — interpretation), ansehen als (to view as — perspective).","examples":[{"sentence":"Er begreift Konflikte als Lernmöglichkeiten.","translation":"He conceives of conflicts as opportunities for learning."},{"sentence":"Die Bewegung begreift Wohnen als Grundrecht, nicht als Ware.","translation":"The movement conceives of housing as a basic right, not a commodity."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Hochwertig'' means?","options":["high-quality","high-value","premium","superior"],"correctAnswer":"high-quality"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The circular economy principle fundamentally calls into question the linear economic model, by keeping materials in the economic cycle for as long as possible and conceiving of waste as a resource.","options":["Das Kreislaufwirtschaftsprinzip stellt das lineare Wirtschaftsmodell grundlegend in Frage, indem es Materialien möglichst lange im Wirtschaftskreislauf hält und Abfall als Ressource begreift.","Kreislaufwirtschaft ersetzt lineares Wirtschaften durch Wiederverwertung.","In der Kreislaufwirtschaft wird Abfall zur Ressource.","Das Ziel ist, Materialien so lange wie möglich im Kreislauf zu halten."],"correctAnswer":"Das Kreislaufwirtschaftsprinzip stellt das lineare Wirtschaftsmodell grundlegend in Frage, indem es Materialien möglichst lange im Wirtschaftskreislauf hält und Abfall als Ressource begreift."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er begreift Konflikte als ___.","options":["Lernmöglichkeiten","Probleme","Herausforderungen","Chancen"],"correctAnswer":"Lernmöglichkeiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The movement conceives of housing as a basic right not a commodity","wordBankItems":["Die","Bewegung","begreift","Wohnen","als","Grundrecht",",","nicht","als","Ware","."],"correctAnswer":"Die Bewegung begreift Wohnen als Grundrecht , nicht als Ware ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Mindern'' means?","options":["to diminish/reduce","to lessen","to decrease","to lower"],"correctAnswer":"to diminish/reduce"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000265',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss green infrastructure at B2","Use Grüne Infrastruktur vocabulary","Talk about renewable energy and sustainable cities"],"explanation":{"intro":"Green infrastructure vocabulary covers renewable energy, sustainable urban planning, and ecological corridors at B2.","culturalNote":"Grüne Infrastruktur: Germany leads in wind and solar (Windkraft, Photovoltaik). Key projects: Offshore-Windparks (North Sea, Baltic), Netzausbau (grid expansion — HVDC lines). Cities: Grüne Städte (green cities — Freiburg as model — solar city, trams, cycling). Key concepts: Ökologische Vernetzung (ecological connectivity — Biotopverbund), Urbane Begrünung (urban greening — Dachgärten, Fassadenbegrünung). EU: Taxonomy for sustainable activities, Nature Restoration Law. Challenges: Akzeptanzprobleme (public acceptance issues — wind turbines near settlements)."},"examples":[{"german":"Der Ausbau grüner Infrastruktur verfolgt einen doppelten Zweck: Er stärkt sowohl die Widerstandsfähigkeit gegen Klimafolgen als auch die biologische Vielfalt in urbanisierten Räumen.","english":"The expansion of green infrastructure pursues a dual purpose: it strengthens both the resilience against the consequences of climate change and biological diversity in urbanised spaces."},{"german":"Freiburg gilt als Paradebeispiel für nachhaltige Stadtentwicklung, weil es schon früh auf dezentrale Energieversorgung, Fahrradinfrastruktur und konsequente Flächennutzungsplanung gesetzt hat.","english":"Freiburg is considered a prime example of sustainable urban development, because it placed its bets early on decentralised energy supply, cycling infrastructure, and consistent land use planning."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss green infrastructure, Freiburg as a model city, and sustainable urban development at B2."}}',
'{"items":[{"word":"verfolgen","translation":"to pursue","pronunciation":"fer-FOL-gen","example":"Einen Zweck verfolgen."},{"word":"der Zweck","translation":"purpose","pronunciation":"dayr tsvek","example":"Doppelter Zweck."},{"word":"die Widerstandsfähigkeit","translation":"resilience","pronunciation":"dee VEE-der-shtants-fä-ikh-kyt","example":"Widerstandsfähigkeit stärken."},{"word":"das Paradebeispiel","translation":"prime example","pronunciation":"dahs pah-rah-DEH-by-shpeel","example":"Paradebeispiel für nachhaltig."},{"word":"dezentral","translation":"decentralised","pronunciation":"day-tsen-TRAHL","example":"Dezentrale Energieversorgung."},{"word":"konsequent","translation":"consistent/consequent","pronunciation":"kon-zeh-KVENT","example":"Konsequente Planung."}]}',
'{"title":"Als X gelten — to be considered/regarded as X (general reputation)","pattern":"etwas/jemand gilt als X = something/someone is considered as X, is regarded as X (reputation or status claim, not just one person''s opinion)","explanation":"Als X gelten = to be considered X, to be regarded as X (refers to a general/shared assessment, not just one viewpoint — opposite of to truly be). Freiburg gilt als Paradebeispiel = Freiburg is considered a prime example (general perception/reputation). Gilt als (present), galt als (simple past), hat als gegolten (perfect — less common). Compare: als X betrachtet werden (to be regarded as X — more neutral/analytical passive), als X angesehen werden (to be viewed as X — more evaluative), als X bezeichnet werden (to be called/referred to as X — labelling/naming). Als X gelten is the go-to for general reputation/status.","examples":[{"sentence":"Er gilt als Experte auf diesem Gebiet.","translation":"He is considered an expert in this field."},{"sentence":"Die Maßnahme gilt als unzureichend.","translation":"The measure is considered insufficient."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Paradebeispiel'' means?","options":["prime example","model example","showcase","benchmark"],"correctAnswer":"prime example"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The expansion of green infrastructure pursues a dual purpose: it strengthens both the resilience against the consequences of climate change and biological diversity in urbanised spaces.","options":["Der Ausbau grüner Infrastruktur verfolgt einen doppelten Zweck: Er stärkt sowohl die Widerstandsfähigkeit gegen Klimafolgen als auch die biologische Vielfalt in urbanisierten Räumen.","Grüne Infrastruktur dient dem Klimaschutz und der Biodiversität.","Grüne Stadtplanung reduziert Klimarisiken und schützt die Natur.","Beim Ausbau grüner Infrastruktur stehen Klimaresilienz und Biodiversität im Fokus."],"correctAnswer":"Der Ausbau grüner Infrastruktur verfolgt einen doppelten Zweck: Er stärkt sowohl die Widerstandsfähigkeit gegen Klimafolgen als auch die biologische Vielfalt in urbanisierten Räumen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er gilt als Experte auf diesem ___.","options":["Gebiet","Bereich","Feld","Thema"],"correctAnswer":"Gebiet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The measure is considered insufficient","wordBankItems":["Die","Maßnahme","gilt","als","unzureichend","."],"correctAnswer":"Die Maßnahme gilt als unzureichend ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Dezentral'' means?","options":["decentralised","distributed","localised","regional"],"correctAnswer":"decentralised"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000266',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the energy transition at B2","Use Energiewende vocabulary","Talk about Germany''s energy policy and challenges"],"explanation":{"intro":"Energy transition vocabulary covers Germany''s Energiewende — its goals, progress, and challenges at B2.","culturalNote":"Energiewende (literally: energy turn): Germany''s policy to transition from fossil fuels to renewables, and out of nuclear (Atomausstieg — 2011 after Fukushima, last reactor 2023). Ziele: 80% renewable electricity by 2030, carbon neutrality by 2045. Progress: 60%+ renewable electricity (2024). Challenges: Netzstabilität (grid stability), Speichertechnologie (storage technology — Pumpspeicher, Batterien), Sektorkopplung (sector coupling — linking electricity to heating and transport), Wasserstoff (hydrogen — as seasonal storage), Windausbau (expanding onshore wind — fighting NIMBYism), gas imports pre-2022. Nord Stream/Ukraine war disruption."},"examples":[{"german":"Die Energiewende erfordert nicht nur den Ausbau erneuerbarer Erzeugungskapazitäten, sondern auch eine tiefgreifende Umgestaltung der Netz- und Speicherinfrastruktur sowie die Kopplung der Sektoren Wärme, Mobilität und Industrie.","english":"The energy transition requires not only the expansion of renewable generation capacities, but also a far-reaching restructuring of the grid and storage infrastructure as well as the coupling of the heat, mobility, and industry sectors."},{"german":"Der Atomausstieg von 2023 war gesellschaftlich weitgehend konsensfähig, intensivierte aber die Debatte über den Ersatz der wegfallenden Grundlastkapazität in einer Zeit, in der Russland als Gaslieferant ausfiel.","english":"The nuclear exit of 2023 was broadly capable of societal consensus, but it intensified the debate about replacing the base-load capacity that would fall away at a time when Russia was failing as a gas supplier."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Energiewende, nuclear exit, and energy transition challenges at B2."}}',
'{"items":[{"word":"tiefgreifend","translation":"far-reaching/profound","pronunciation":"TEEF-gry-fend","example":"Tiefgreifende Umgestaltung."},{"word":"die Umgestaltung","translation":"restructuring/reshaping","pronunciation":"dee OOM-geh-shtal-toong","example":"Umgestaltung der Infrastruktur."},{"word":"die Kopplung","translation":"coupling/linkage","pronunciation":"dee KOP-loong","example":"Sektorkopplung."},{"word":"konsensfähig","translation":"capable of consensus","pronunciation":"kon-ZENS-fä-ikh","example":"Gesellschaftlich konsensfähig."},{"word":"die Grundlast","translation":"base-load","pronunciation":"dee GROONT-last","example":"Grundlastkapazität."},{"word":"wegfallen","translation":"to fall away/cease to exist","pronunciation":"VEK-fal-en","example":"Kapazitäten fallen weg."}]}',
'{"title":"In einer Zeit, in der X — at a time when X (historical context clause)","pattern":"in einer Zeit, in der X = at a time when X (defines the historical moment of the main clause — in der is a relative clause modifier of Zeit)","explanation":"In einer Zeit, in der X = at a time when X (in der = relative pronoun referring back to Zeit — feminine — in + der = in der). Marks the historical/temporal context that makes the main clause significant or difficult. Intensivierte die Debatte in einer Zeit, in der Russland ausfiel = intensified the debate at a time when Russia was failing. In einer Zeit is more literary/formal than zu einer Zeit (same meaning, less formal). Often used to contextualise a challenge: the time modifier explains why something was especially consequential.","examples":[{"sentence":"In einer Zeit, in der die Demokratie unter Druck gerät, ist kritisches Denken besonders wichtig.","translation":"At a time when democracy is coming under pressure, critical thinking is particularly important."},{"sentence":"Sie schrieb in einer Zeit, in der Frauen kaum öffentlich gehört wurden.","translation":"She wrote at a time when women were barely heard publicly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Tiefgreifend'' means?","options":["far-reaching/profound","deep-rooted","fundamental","thoroughgoing"],"correctAnswer":"far-reaching/profound"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The energy transition requires not only the expansion of renewable generation capacities, but also a far-reaching restructuring of the grid and storage infrastructure as well as the coupling of the heat, mobility, and industry sectors.","options":["Die Energiewende erfordert nicht nur den Ausbau erneuerbarer Erzeugungskapazitäten, sondern auch eine tiefgreifende Umgestaltung der Netz- und Speicherinfrastruktur sowie die Kopplung der Sektoren Wärme, Mobilität und Industrie.","Die Energiewende umfasst Windkraft, Solar und eine neue Infrastruktur.","Deutschland baut erneuerbare Energien aus und gestaltet die Infrastruktur um.","Die Energiewende betrifft alle Bereiche der Wirtschaft."],"correctAnswer":"Die Energiewende erfordert nicht nur den Ausbau erneuerbarer Erzeugungskapazitäten, sondern auch eine tiefgreifende Umgestaltung der Netz- und Speicherinfrastruktur sowie die Kopplung der Sektoren Wärme, Mobilität und Industrie."},{"id":"ex3","type":"FILL_IN_BLANK","question":"In einer Zeit, in der die Demokratie unter Druck gerät, ist kritisches Denken besonders ___.","options":["wichtig","notwendig","relevant","bedeutsam"],"correctAnswer":"wichtig"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: At a time when democracy is coming under pressure critical thinking is particularly important","wordBankItems":["In","einer","Zeit",",","in","der","die","Demokratie","unter","Druck","gerät",",","ist","kritisches","Denken","besonders","wichtig","."],"correctAnswer":"In einer Zeit , in der die Demokratie unter Druck gerät , ist kritisches Denken besonders wichtig ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Wegfallen'' means?","options":["to fall away/cease to exist","to disappear","to drop off","to be lost"],"correctAnswer":"to fall away/cease to exist"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000267',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss climate finance at B2","Use Klimafinanzierung vocabulary","Talk about climate investments and carbon markets"],"explanation":{"intro":"Climate finance vocabulary covers public and private financing of climate mitigation and adaptation at B2.","culturalNote":"Klimafinanzierung: 100 Milliarden Dollar Ziel (developed nations pledged $100bn/yr to developing countries by 2020 — missed, late). COP (UN Climate Conferences — Paris, Glasgow, Dubai). Key instruments: Grüne Anleihen (green bonds), EU Taxonomie (taxonomy — which activities are ''green''), Emissionshandel (emissions trading — EU ETS, price of CO2 per tonne). Germany: Klimaschutzprogramm, Klima- und Transformationsfonds (CTF). Key debate: Loss and Damage Fonds (climate reparations for developing nations — agreed COP27/28). Voluntary carbon markets vs. regulated systems."},"examples":[{"german":"Die Klimafinanzierung steht vor der Herausforderung, private Investitionsströme in klimaverträgliche Infrastruktur umzulenken — eine Aufgabe, die verlässliche Politiksignale, klare Taxonomien und langfristige Planungssicherheit erfordert.","english":"Climate finance faces the challenge of redirecting private investment flows into climate-compatible infrastructure — a task that requires reliable policy signals, clear taxonomies, and long-term planning certainty."},{"german":"Das Emissionshandelssystem der EU setzt Kohlenstoffdioxid einen Preis, um wirtschaftliche Anreize für Emissionsreduktionen zu setzen — sein Erfolg hängt jedoch entscheidend von einem ausreichend hohen Zertifikatspreise ab.","english":"The EU''s emissions trading system puts a price on carbon dioxide in order to set economic incentives for emissions reductions — its success depends decisively, however, on a sufficiently high certificate price."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss climate finance, carbon pricing, and green bond taxonomy at B2."}}',
'{"items":[{"word":"umlenken","translation":"to redirect","pronunciation":"OOM-len-ken","example":"Investitionsströme umlenken."},{"word":"klimaverträglich","translation":"climate-compatible","pronunciation":"KLEE-mah-fer-träk-likh","example":"Klimaverträgliche Infrastruktur."},{"word":"die Planungssicherheit","translation":"planning certainty","pronunciation":"dee PLAH-noonks-zi-kher-kyt","example":"Langfristige Planungssicherheit."},{"word":"der Zertifikatspreis","translation":"certificate price","pronunciation":"dayr tser-ti-fi-KAHTS-prys","example":"Zertifikatspreise."},{"word":"ausreichend","translation":"sufficient/adequate","pronunciation":"OWS-ry-khend","example":"Ausreichend hoch."},{"word":"der Investitionsstrom","translation":"investment flow","pronunciation":"dayr in-ves-ti-TSYOHNS-shtrom","example":"Investitionsströme."}]}',
'{"title":"Um X umzulenken — to redirect X (purpose clause with infinitive)","pattern":"um etwas umzulenken = in order to redirect something (um...zu + infinitive of separable verb: umlenken → umzulenken — zu inserts between prefix and stem)","explanation":"Um...zu + infinitive = in order to (purpose clause). Separable verb: umlenken = um + lenken → um...zu...lenken → umzulenken (zu inserted between prefix and stem). Um private Investitionsströme umzulenken = in order to redirect private investment flows. Common error: *um private Investitionsströme zu umlenken (wrong — zu does NOT come before the whole separable verb). The prefix stays fused: umzulenken. Same for: umzugestalten, wegzulenken, abzuzweigen.","examples":[{"sentence":"Sie arbeiten daran, staatliche Mittel umzulenken.","translation":"They are working to redirect public funds."},{"sentence":"Das Ziel ist, Ressourcen in benachteiligte Regionen umzulenken.","translation":"The goal is to redirect resources into disadvantaged regions."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausreichend'' means?","options":["sufficient/adequate","enough","satisfactory","acceptable"],"correctAnswer":"sufficient/adequate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Climate finance faces the challenge of redirecting private investment flows into climate-compatible infrastructure — a task that requires reliable policy signals, clear taxonomies, and long-term planning certainty.","options":["Die Klimafinanzierung steht vor der Herausforderung, private Investitionsströme in klimaverträgliche Infrastruktur umzulenken — eine Aufgabe, die verlässliche Politiksignale, klare Taxonomien und langfristige Planungssicherheit erfordert.","Klimafinanzierung bedeutet, privates Kapital für klimafreundliche Projekte zu mobilisieren.","Die Herausforderung besteht darin, private Investitionen in nachhaltige Infrastruktur zu lenken.","Klare Rahmenbedingungen sind nötig, um Klimainvestitionen anzureizen."],"correctAnswer":"Die Klimafinanzierung steht vor der Herausforderung, private Investitionsströme in klimaverträgliche Infrastruktur umzulenken — eine Aufgabe, die verlässliche Politiksignale, klare Taxonomien und langfristige Planungssicherheit erfordert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Ziel ist, Ressourcen in benachteiligte Regionen ___.","options":["umzulenken","umzuleiten","zu lenken","hinzulenken"],"correctAnswer":"umzulenken"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: They are working to redirect public funds","wordBankItems":["Sie","arbeiten","daran",",","staatliche","Mittel","umzulenken","."],"correctAnswer":"Sie arbeiten daran , staatliche Mittel umzulenken ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Klimaverträglich'' means?","options":["climate-compatible","climate-friendly","climate-neutral","climate-safe"],"correctAnswer":"climate-compatible"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000268',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss CSR at B2","Use Unternehmensverantwortung vocabulary","Talk about corporate responsibility and ESG"],"explanation":{"intro":"Corporate Social Responsibility vocabulary covers ESG frameworks, stakeholder theory, and social enterprise at B2.","culturalNote":"Unternehmensverantwortung (Corporate Social Responsibility, CSR): Drei Dimensionen (three dimensions — social, environmental, governance). ESG (Environmental, Social, Governance — for investors). Germany: Lieferkettensorgfaltspflichtengesetz (Supply Chain Due Diligence Act — 2023, over 3,000 employees — check for human rights/environment violations in supply chains). Gemeinnützige GmbH (gGmbH — public benefit limited company). B-Corp movement. Kritik: Greenwashing, Sozialwashing, CSR as PR. Key concept: Shareholder value vs. Stakeholder value. Milton Friedman (1970) — business has one responsibility: profit. Counterpoint: Freeman (stakeholder theory)."},"examples":[{"german":"Die gesetzliche Verankerung von Sorgfaltspflichten entlang globaler Lieferketten markiert einen Paradigmenwechsel: Unternehmen werden nicht mehr nur für ihr Handeln im Inland, sondern auch für das ihrer Zulieferer im Ausland verantwortlich gemacht.","english":"The legal anchoring of due diligence obligations along global supply chains marks a paradigm shift: companies are no longer made responsible only for their conduct domestically, but also for that of their suppliers abroad."},{"german":"CSR-Engagement ist nur dann glaubwürdig, wenn es in der Unternehmenskultur und Governance verankert ist statt als Marketinginstrument zur Imageoptimierung genutzt zu werden.","english":"CSR engagement is only credible when it is anchored in corporate culture and governance rather than being used as a marketing instrument for image optimisation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss CSR, ESG, supply chain due diligence, and greenwashing at B2."}}',
'{"items":[{"word":"die Verankerung","translation":"anchoring/embedding","pronunciation":"dee fer-AN-ker-oong","example":"Gesetzliche Verankerung."},{"word":"die Sorgfaltspflicht","translation":"due diligence obligation","pronunciation":"dee ZORK-falts-pflikt","example":"Sorgfaltspflichten."},{"word":"der Paradigmenwechsel","translation":"paradigm shift","pronunciation":"dayr pah-rah-DIG-men-vek-sel","example":"Paradigmenwechsel markieren."},{"word":"verantwortlich machen für","translation":"to hold responsible for","pronunciation":"fer-ANT-vort-likh MA-khen für","example":"Verantwortlich machen."},{"word":"glaubwürdig","translation":"credible","pronunciation":"GLOUB-vür-dikh","example":"Glaubwürdig sein."},{"word":"die Imageoptimierung","translation":"image optimisation","pronunciation":"dee I-mij-op-ti-mee-roong","example":"Imageoptimierung."}]}',
'{"title":"Statt X zu werden/sein — instead of X-ing / instead of being X (contrast with infinitive clause)","pattern":"statt X zu + infinitive = instead of X-ing (statt = instead of — can precede an infinitive clause or a noun phrase; marks a rejected alternative)","explanation":"Statt + infinitive clause = instead of doing X. Statt als Marketinginstrument genutzt zu werden = instead of being used as a marketing instrument. Statt can also precede a noun (statt eines Instruments). This is one of the ''um/ohne/statt + zu'' group (purposive/restrictive infinitives without dass-clause). The infinitive is always last. With sein/werden verbs: statt...zu sein, statt...zu werden, statt...genutzt zu werden (passive). Compare: anstatt (= statt, slightly more formal), anstelle von + noun (instead of + noun).","examples":[{"sentence":"Anstatt die Probleme anzugehen, wurde abgelenkt.","translation":"Instead of addressing the problems, a distraction was made."},{"sentence":"Er sprach offen, statt auszuweichen.","translation":"He spoke openly instead of evading."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Paradigmenwechsel'' means?","options":["paradigm shift","fundamental change","sea change","turning point"],"correctAnswer":"paradigm shift"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The legal anchoring of due diligence obligations along global supply chains marks a paradigm shift: companies are no longer made responsible only for their conduct domestically, but also for that of their suppliers abroad.","options":["Die gesetzliche Verankerung von Sorgfaltspflichten entlang globaler Lieferketten markiert einen Paradigmenwechsel: Unternehmen werden nicht mehr nur für ihr Handeln im Inland, sondern auch für das ihrer Zulieferer im Ausland verantwortlich gemacht.","Das Lieferkettengesetz macht Unternehmen für Menschenrechtsverletzungen ihrer Zulieferer haftbar.","Neue Gesetze verpflichten Unternehmen, Menschenrechte entlang ihrer Lieferketten zu schützen.","Unternehmen müssen nun auch für Missstände bei Zulieferern im Ausland geradestehen."],"correctAnswer":"Die gesetzliche Verankerung von Sorgfaltspflichten entlang globaler Lieferketten markiert einen Paradigmenwechsel: Unternehmen werden nicht mehr nur für ihr Handeln im Inland, sondern auch für das ihrer Zulieferer im Ausland verantwortlich gemacht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er sprach offen, statt ___.","options":["auszuweichen","auszuweichen","zu schweigen","aufzugeben"],"correctAnswer":"auszuweichen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Instead of addressing the problems a distraction was made","wordBankItems":["Anstatt","die","Probleme","anzugehen",",","wurde","abgelenkt","."],"correctAnswer":"Anstatt die Probleme anzugehen , wurde abgelenkt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Glaubwürdig'' means?","options":["credible","trustworthy","authentic","reliable"],"correctAnswer":"credible"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000269',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss supply chains at B2","Use Lieferketten vocabulary","Talk about global supply chains and resilience"],"explanation":{"intro":"Supply chain vocabulary covers global production networks, risks, and resilience strategies at B2.","culturalNote":"Lieferketten (supply chains): Just-in-Time (JIT — lean production — invented Toyota, adopted widely — exposed in COVID). COVID Lieferkettenunterbrechungen (disruptions — computer chips, PPE). Russia-Ukraine War: energy and food supply chains disrupted. Germany: Lieferkettensorgfaltspflichtengesetz (2023). Key concepts: Reshoring (production back to domestic), Nearshoring (to nearby countries), Diversifizierung (diversification), Dual Sourcing. Key vulnerabilities: China for rare earths (Seltene Erden), Taiwan for chips, Russia for gas. Begriff: strategische Abhängigkeit (strategic dependency) vs. strategische Autonomie (strategic autonomy)."},"examples":[{"german":"Die Verwundbarkeit globaler Lieferketten wurde durch die Pandemie schonungslos offengelegt: Hochgradig optimierte Just-in-Time-Systeme erweisen sich als fragil gegenüber unvorhergesehenen Schocks.","english":"The vulnerability of global supply chains was mercilessly exposed by the pandemic: highly optimised just-in-time systems prove fragile against unforeseen shocks."},{"german":"Europas Bemühungen um strategische Autonomie stoßen auf das Dilemma, dass Reshoring und Diversifizierung kurzfristig Effizienzkosten verursachen, langfristig aber Resilienz und Versorgungssicherheit erhöhen.","english":"Europe''s efforts towards strategic autonomy encounter the dilemma that reshoring and diversification cause efficiency costs in the short term, but increase resilience and supply security in the long term."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss global supply chains, vulnerabilities, and strategic autonomy at B2."}}',
'{"items":[{"word":"die Verwundbarkeit","translation":"vulnerability","pronunciation":"dee fer-VOOND-bahr-kyt","example":"Verwundbarkeit der Lieferketten."},{"word":"schonungslos","translation":"mercilessly/ruthlessly","pronunciation":"SHOH-noonks-los","example":"Schonungslos offenlegen."},{"word":"hochgradig","translation":"highly (to a high degree)","pronunciation":"HOHKH-grah-dikh","example":"Hochgradig optimiert."},{"word":"fragil","translation":"fragile","pronunciation":"frah-GEEL","example":"Fragil gegenüber Schocks."},{"word":"stoßen auf","translation":"to encounter/run into","pronunciation":"SHTOH-sen owf","example":"Auf Dilemma stoßen."},{"word":"die Versorgungssicherheit","translation":"supply security","pronunciation":"dee fer-ZOR-goonks-zi-kher-kyt","example":"Versorgungssicherheit erhöhen."}]}',
'{"title":"Auf etwas stoßen — to encounter, to run into (an obstacle, dilemma, or resistance)","pattern":"jemand/etwas stößt auf X = someone/something encounters X, runs into X (auf stoßen = to come up against — used for obstacles, unexpected resistance, discoveries, dilemmas)","explanation":"Auf etwas stoßen = to encounter, to come across, to run into (stoßen = to push/hit — auf etwas stoßen = to hit upon something). Europas Bemühungen stoßen auf das Dilemma = Europe''s efforts run into the dilemma. Two uses: 1) encounter an obstacle/problem (as here), 2) come across/find something: auf einen Fehler stoßen (to come across an error), auf eine Idee stoßen (to come upon an idea). Separable: stößt ... auf (present), stieß ... auf (simple past), ist ... gestoßen (perfect — sein). Compare: treffen auf (to meet/encounter — more neutral), stoßen auf (more of a finding/hitting-upon quality).","examples":[{"sentence":"Das Projekt stieß auf unerwartet starken Widerstand.","translation":"The project ran into unexpectedly strong resistance."},{"sentence":"Bei der Recherche bin ich auf interessante Dokumente gestoßen.","translation":"In my research I came across interesting documents."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schonungslos'' means?","options":["mercilessly","ruthlessly","bluntly","unsparing"],"correctAnswer":"mercilessly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The vulnerability of global supply chains was mercilessly exposed by the pandemic: highly optimised just-in-time systems prove fragile against unforeseen shocks.","options":["Die Verwundbarkeit globaler Lieferketten wurde durch die Pandemie schonungslos offengelegt: Hochgradig optimierte Just-in-Time-Systeme erweisen sich als fragil gegenüber unvorhergesehenen Schocks.","Die Pandemie hat die Schwächen globaler Lieferketten aufgezeigt.","Just-in-Time-Produktion ist anfällig für globale Krisen.","Die COVID-Krise hat gezeigt, wie fragil globale Lieferketten sind."],"correctAnswer":"Die Verwundbarkeit globaler Lieferketten wurde durch die Pandemie schonungslos offengelegt: Hochgradig optimierte Just-in-Time-Systeme erweisen sich als fragil gegenüber unvorhergesehenen Schocks."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt stieß auf unerwartet starken ___.","options":["Widerstand","Widerspruch","Protest","Ablehnung"],"correctAnswer":"Widerstand"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In my research I came across interesting documents","wordBankItems":["Bei","der","Recherche","bin","ich","auf","interessante","Dokumente","gestoßen","."],"correctAnswer":"Bei der Recherche bin ich auf interessante Dokumente gestoßen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Fragil'' means?","options":["fragile","brittle","delicate","vulnerable"],"correctAnswer":"fragile"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000026a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss development economics at B2","Use Entwicklungsökonomie vocabulary","Talk about global inequality and aid effectiveness"],"explanation":{"intro":"Development economics vocabulary covers theories of development, global inequality, and aid at B2.","culturalNote":"Entwicklungsökonomie: Germany is one of world''s largest aid donors (ODA — Official Development Assistance). BMZ (Bundesministerium für wirtschaftliche Zusammenarbeit und Entwicklung). GIZ (Deutsche Gesellschaft für Internationale Zusammenarbeit — implements German development cooperation). Development theories: Modernisation theory, Dependency theory (Dependenztheorie), Amartya Sen (capabilities approach — Entwicklung als Freiheit). Milleniumsentwicklungsziele (MDGs → SDGs). Key debates: Wirksamkeit von Entwicklungshilfe (aid effectiveness — Easterly vs. Sachs), Konditionalität (conditionality — IMF/World Bank structural adjustment). Fair trade (Fairer Handel)."},"examples":[{"german":"Der Capabilities-Ansatz von Amartya Sen verschiebt den Fokus der Entwicklungsökonomie von materiellem Wohlstand auf die tatsächliche Fähigkeit von Menschen, ein selbstbestimmtes und gelingendes Leben zu führen.","english":"Amartya Sen''s capabilities approach shifts the focus of development economics from material wealth to the actual ability of people to lead a self-determined and flourishing life."},{"german":"Die Wirksamkeit von Entwicklungshilfe ist umstritten: Während einige Ökonomen auf messbaren Fortschritt verweisen, argumentieren andere, dass Hilfe Abhängigkeit erzeugt und lokale Märkte untergräbt.","english":"The effectiveness of development aid is contested: while some economists point to measurable progress, others argue that aid creates dependency and undermines local markets."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss development economics, Sen''s capabilities approach, and aid effectiveness debates at B2."}}',
'{"items":[{"word":"verschieben","translation":"to shift","pronunciation":"fer-SHEE-ben","example":"Den Fokus verschieben."},{"word":"selbstbestimmt","translation":"self-determined","pronunciation":"ZELPST-beh-shtimmt","example":"Selbstbestimmtes Leben."},{"word":"gelingend","translation":"flourishing/successful","pronunciation":"geh-LING-end","example":"Gelingendes Leben."},{"word":"umstritten","translation":"contested/controversial","pronunciation":"oom-SHTRIT-en","example":"Umstritten ist."},{"word":"verweisen auf","translation":"to point to/refer to","pronunciation":"fer-VY-zen owf","example":"Auf Fortschritt verweisen."},{"word":"untergraben","translation":"to undermine","pronunciation":"oon-ter-GRAH-ben","example":"Märkte untergraben."}]}',
'{"title":"Während A, argumentieren B, dass... — while A, B argue that... (contrast in academic/political discourse)","pattern":"Während A X, argumentieren B, dass Y = While A [state/claim] X, B argue that Y (während = while — temporal or concessive; here: concessive/contrastive — two opposing views in one sentence)","explanation":"Während...argumentieren...dass = While [group A claims X], [group B] argue that Y. Während (while) here is concessive = although, even though — not purely temporal. Common in academic/political discourse to present a debate (present opposing views concisely). Structure: Während A + verb, B + verb + dass. The two main views are clearly separated. Compare: Einerseits...andererseits (on the one hand...on the other hand — more explicit contrast), Manche...andere (some...others — similar but less formal contrast), Im Gegensatz dazu (in contrast to that — between sentences).","examples":[{"sentence":"Während Befürworter auf Erfolge verweisen, warnen Kritiker vor Nebenwirkungen.","translation":"While supporters point to successes, critics warn of side effects."},{"sentence":"Während manche Kosten betonen, sehen andere langfristigen Nutzen.","translation":"While some emphasise costs, others see long-term benefits."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Umstritten'' means?","options":["contested/controversial","debated","disputed","contentious"],"correctAnswer":"contested/controversial"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The effectiveness of development aid is contested: while some economists point to measurable progress, others argue that aid creates dependency and undermines local markets.","options":["Die Wirksamkeit von Entwicklungshilfe ist umstritten: Während einige Ökonomen auf messbaren Fortschritt verweisen, argumentieren andere, dass Hilfe Abhängigkeit erzeugt und lokale Märkte untergräbt.","Entwicklungshilfe ist effektiv, wenn sie richtig eingesetzt wird.","Manche sehen Entwicklungshilfe als sinnvoll, andere als kontraproduktiv.","Die Debatte über Entwicklungshilfe dreht sich um ihre langfristige Wirkung."],"correctAnswer":"Die Wirksamkeit von Entwicklungshilfe ist umstritten: Während einige Ökonomen auf messbaren Fortschritt verweisen, argumentieren andere, dass Hilfe Abhängigkeit erzeugt und lokale Märkte untergräbt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Während Befürworter auf Erfolge verweisen, warnen Kritiker vor ___.","options":["Nebenwirkungen","Konsequenzen","Schäden","Problemen"],"correctAnswer":"Nebenwirkungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: While some emphasise costs others see long-term benefits","wordBankItems":["Während","manche","Kosten","betonen",",","sehen","andere","langfristigen","Nutzen","."],"correctAnswer":"Während manche Kosten betonen , sehen andere langfristigen Nutzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Untergraben'' means?","options":["to undermine","to erode","to sabotage","to destabilise"],"correctAnswer":"to undermine"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000026b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss economic sanctions at B2","Use Wirtschaftssanktionen vocabulary","Talk about sanctions regimes and economic coercion"],"explanation":{"intro":"Economic sanctions vocabulary covers sanctions policy, effectiveness, and Germany''s experience at B2.","culturalNote":"Wirtschaftssanktionen: Economic coercion using trade/finance. Germany: Russia sanctions post-2022 (Exportverbote — export bans, Einfrieren von Vermögen — asset freezes, SWIFT-Ausschluss — SWIFT exclusion for Russian banks, Ölpreisdeckel — oil price cap). Kosten (costs): Germany highly dependent on Russian gas (Nordgas, Nordstream). Types: primäre Sanktionen (direct restrictions) and sekundäre Sanktionen (against third countries that do business with sanctioned entity). Key debate: Wirksamkeit (effectiveness — do they change behaviour?). Extraterritoriale US-Sanktionen (US secondary sanctions — JCPOA, CAATSA). EU autonomy debate."},"examples":[{"german":"Sanktionen sind ein zweischneidiges Instrument der Außenpolitik: Sie senden ein klares politisches Signal und verursachen wirtschaftliche Kosten für das Zielland, können aber auch Drittstaaten und die Sanktionierenden selbst belasten.","english":"Sanctions are a double-edged instrument of foreign policy: they send a clear political signal and cause economic costs for the target country, but can also burden third states and the sanctioners themselves."},{"german":"Die rasche Einigung der EU auf ein umfassendes Sanktionspaket gegen Russland nach dem Einmarsch in die Ukraine markierte eine historische Geschlossenheit, die angesichts der wirtschaftlichen Abhängigkeiten keineswegs selbstverständlich war.","english":"The rapid agreement of the EU on a comprehensive sanctions package against Russia after the invasion of Ukraine marked a historical unity that was by no means self-evident given the economic dependencies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss economic sanctions, Russia sanctions, and sanctions effectiveness at B2."}}',
'{"items":[{"word":"zweischneidig","translation":"double-edged","pronunciation":"TSVY-shnye-dikh","example":"Zweischneidiges Instrument."},{"word":"belasten","translation":"to burden","pronunciation":"beh-LAS-ten","example":"Drittstaaten belasten."},{"word":"die Geschlossenheit","translation":"unity","pronunciation":"dee geh-SHLOS-en-kyt","example":"Historische Geschlossenheit."},{"word":"keineswegs","translation":"by no means","pronunciation":"KY-nes-veks","example":"Keineswegs selbstverständlich."},{"word":"angesichts","translation":"given/in view of","pronunciation":"AN-geh-zikhts","example":"Angesichts der Abhängigkeiten."},{"word":"umfassend","translation":"comprehensive","pronunciation":"OOM-fas-end","example":"Umfassendes Paket."}]}',
'{"title":"Angesichts + genitive — given, in view of (prepositional phrase marking context)","pattern":"angesichts + genitive = given, in view of, in the face of (marks the contextual factor that makes the main clause noteworthy or surprising)","explanation":"Angesichts (preposition) = given, in view of, in the face of. Always followed by genitive: angesichts der wirtschaftlichen Abhängigkeiten = given the economic dependencies (die Abhängigkeiten → der Abhängigkeiten in genitive). The angesichts phrase marks something that makes the main clause surprising, difficult, or significant: angesichts X war Y bemerkenswert = given X, Y was remarkable. Compare: angesichts (given — emphasises challenge/contrast), trotz + genitive (despite — stronger concession), im Hinblick auf (with regard to — more neutral analytical).","examples":[{"sentence":"Angesichts der schwierigen Lage ist das Ergebnis bemerkenswert.","translation":"Given the difficult situation, the result is remarkable."},{"sentence":"Angesichts steigender Energiepreise wurde die Industriepolitik neu ausgerichtet.","translation":"In view of rising energy prices, industrial policy was realigned."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Keineswegs'' means?","options":["by no means","not at all","in no way","never"],"correctAnswer":"by no means"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Sanctions are a double-edged instrument of foreign policy: they send a clear political signal and cause economic costs for the target country, but can also burden third states and the sanctioners themselves.","options":["Sanktionen sind ein zweischneidiges Instrument der Außenpolitik: Sie senden ein klares politisches Signal und verursachen wirtschaftliche Kosten für das Zielland, können aber auch Drittstaaten und die Sanktionierenden selbst belasten.","Sanktionen schaden dem Zielland, können aber auch eigene Wirtschaft belasten.","Wirtschaftssanktionen sind ein außenpolitisches Mittel mit Vor- und Nachteilen.","Sanktionen senden Signale, belasten aber alle Beteiligten."],"correctAnswer":"Sanktionen sind ein zweischneidiges Instrument der Außenpolitik: Sie senden ein klares politisches Signal und verursachen wirtschaftliche Kosten für das Zielland, können aber auch Drittstaaten und die Sanktionierenden selbst belasten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Angesichts der schwierigen Lage ist das Ergebnis ___.","options":["bemerkenswert","erstaunlich","positiv","überraschend"],"correctAnswer":"bemerkenswert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In view of rising energy prices industrial policy was realigned","wordBankItems":["Angesichts","steigender","Energiepreise","wurde","die","Industriepolitik","neu","ausgerichtet","."],"correctAnswer":"Angesichts steigender Energiepreise wurde die Industriepolitik neu ausgerichtet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Umfassend'' means?","options":["comprehensive","extensive","broad","wide-ranging"],"correctAnswer":"comprehensive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000026c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss geopolitics of resources at B2","Use Rohstoff-Geopolitik vocabulary","Talk about critical materials and strategic dependencies"],"explanation":{"intro":"Resource geopolitics vocabulary covers critical materials, strategic dependencies, and resource competition at B2.","culturalNote":"Geopolitik der Rohstoffe: Kritische Rohstoffe (critical raw materials — EU list: rare earths, lithium, cobalt, silicon, tungsten, platinum). China dominates many critical materials (Seltene Erden, Lithium-Verarbeitung). Germany: hochgradig abhängig (highly dependent — imports most raw materials). Energierohstoffe (energy resources — oil: OPEC, gas: Russia). Key concepts: Ressourcenfluch (resource curse — wealth from resources without institutions), Rohstoffdiplomatie (resource diplomacy — securing supplies via partnerships), kritische Infrastruktur (critical infrastructure). German initiatives: Rohstoffpartnerschaften (raw material partnerships — with DRC, Namibia, Chile)."},"examples":[{"german":"Die geopolitische Dimension des ökologischen Umbaus wird oft unterschätzt: Erneuerbare Energien erfordern große Mengen kritischer Mineralien, deren Förderung und Verarbeitung in wenigen Ländern konzentriert ist.","english":"The geopolitical dimension of the ecological transformation is often underestimated: renewable energies require large quantities of critical minerals, the extraction and processing of which is concentrated in a few countries."},{"german":"Deutschland reagiert auf seine Rohstoffabhängigkeit mit einer Diversifizierungsstrategie, die Rohstoffpartnerschaften mit ressourcenreichen Ländern des Globalen Südens schließt — eine Strategie, die wirtschaftliche und geopolitische Interessen verbindet.","english":"Germany responds to its raw material dependency with a diversification strategy that concludes raw material partnerships with resource-rich countries of the Global South — a strategy that combines economic and geopolitical interests."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss resource geopolitics, critical minerals, and Germany''s raw material strategy at B2."}}',
'{"items":[{"word":"unterschätzen","translation":"to underestimate","pronunciation":"oon-ter-SHÄT-sen","example":"Die Dimension unterschätzen."},{"word":"die Förderung","translation":"extraction/mining","pronunciation":"dee FÖR-der-oong","example":"Förderung von Mineralien."},{"word":"konzentriert","translation":"concentrated","pronunciation":"kon-tsen-TREERT","example":"Konzentriert in wenigen Ländern."},{"word":"ressourcenreich","translation":"resource-rich","pronunciation":"reh-ZOOR-tsen-rysh","example":"Ressourcenreiche Länder."},{"word":"die Abhängigkeit","translation":"dependency","pronunciation":"dee ap-HÄN-ikh-kyt","example":"Rohstoffabhängigkeit."},{"word":"reagieren auf","translation":"to respond to","pronunciation":"reh-ah-GEER-en owf","example":"Auf Abhängigkeit reagieren."}]}',
'{"title":"Deren X + verb — whose X / the X of which (genitive relative pronoun)","pattern":"deren + noun = whose / of which (genitive relative pronoun — deren refers to a feminine or plural noun preceding it — replaces genitive article + noun for concise relative clause)","explanation":"Deren = genitive relative pronoun for feminine singular and all plurals. Mineralien, deren Förderung in wenigen Ländern konzentriert ist = minerals, the extraction of which is concentrated in a few countries. Deren replaces ''der/die/das Förderung dieser Mineralien'' in a relative clause. Masculine/neuter singular: dessen. Feminine/plural: deren. deren Verarbeitung = their processing; deren Nutzung = their use; deren Kosten = their costs. Very common in formal/academic German to avoid repeating the antecedent noun. Compare: von denen (from/of which — non-genitive), was (which — for whole clauses).","examples":[{"sentence":"Eine Technologie, deren Kosten rapide sinken, ist Solar.","translation":"A technology whose costs are falling rapidly is solar."},{"sentence":"Unternehmen, deren Kernkompetenz hier liegt, haben Vorteile.","translation":"Companies whose core competence lies here have advantages."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unterschätzen'' means?","options":["to underestimate","to undervalue","to overlook","to minimise"],"correctAnswer":"to underestimate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The geopolitical dimension of the ecological transformation is often underestimated: renewable energies require large quantities of critical minerals, the extraction and processing of which is concentrated in a few countries.","options":["Die geopolitische Dimension des ökologischen Umbaus wird oft unterschätzt: Erneuerbare Energien erfordern große Mengen kritischer Mineralien, deren Förderung und Verarbeitung in wenigen Ländern konzentriert ist.","Erneuerbare Energien haben geopolitische Konsequenzen wegen ihrer Rohstoffabhängigkeit.","Der ökologische Umbau erfordert Rohstoffe, die nur in wenigen Ländern vorkommen.","Für Erneuerbare Energien braucht man kritische Mineralien, die selten sind."],"correctAnswer":"Die geopolitische Dimension des ökologischen Umbaus wird oft unterschätzt: Erneuerbare Energien erfordern große Mengen kritischer Mineralien, deren Förderung und Verarbeitung in wenigen Ländern konzentriert ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Eine Technologie, deren Kosten rapide sinken, ist ___.","options":["Solar","Wind","Wasser","Kernkraft"],"correctAnswer":"Solar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Companies whose core competence lies here have advantages","wordBankItems":["Unternehmen",",","deren","Kernkompetenz","hier","liegt",",","haben","Vorteile","."],"correctAnswer":"Unternehmen , deren Kernkompetenz hier liegt , haben Vorteile ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Konzentriert'' means?","options":["concentrated","focused","centralised","clustered"],"correctAnswer":"concentrated"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

